return ['domain'=>'dosieci-seo-doctor','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'DoSieci SEO Doctor 1.0.0','pot-creation-date'=>'2026-09-24T20:18:34+00:00','po-revision-date'=>'2026-09-24T20:18:34+00:00','messages'=>['DoSieci SEO Doctor'=>'DoSieci SEO Doctor','https://dosieci.pl/wtyczki/seo-doctor/'=>'https://dosieci.pl/wtyczki/seo-doctor/','A read-only SEO audit of posts, pages and WooCommerce products, with optional AI suggestions for titles and descriptions. Works alongside Yoast SEO, Rank Math, All in One SEO and SEOPress instead of replacing them.'=>'Audyt SEO wpisów, stron i produktów WooCommerce wyłącznie do odczytu, z opcjonalnymi podpowiedziami AI dla tytułów i opisów. Współpracuje z Yoast SEO, Rank Math, All in One SEO i SEOPress zamiast je zastępować.','DoSieci'=>'DoSieci','https://dosieci.pl/'=>'https://dosieci.pl/','OpenAI rejected the API key. Check the key in the settings below.'=>'OpenAI odrzuciło klucz API. Sprawdź klucz w ustawieniach poniżej.','OpenAI does not recognise this model name, or your key has no access to it. Check the model in the settings below.'=>'OpenAI nie rozpoznaje tej nazwy modelu albo Twój klucz nie ma do niego dostępu. Sprawdź model w ustawieniach poniżej.','OpenAI rate limit or quota reached. Try again in a moment, or check the billing of your OpenAI account.'=>'Osiągnięto limit zapytań lub budżetu w OpenAI. Spróbuj ponownie za chwilę albo sprawdź rozliczenia swojego konta OpenAI.','OpenAI returned HTTP error %d.'=>'OpenAI zwróciło błąd HTTP %d.','OpenAI returned an empty answer.'=>'OpenAI zwróciło pustą odpowiedź.','There is no title.'=>'Brak tytułu.','Add a title. Without one, search engines make up their own.'=>'Dodaj tytuł — bez niego wyszukiwarka wymyśli własny.','The title is %d character long, which is short.'=>'Tytuł ma tylko %d znak — to za mało.' . "\0" . 'Tytuł ma tylko %d znaki — to za mało.' . "\0" . 'Tytuł ma tylko %d znaków — to za mało.','Expand it to %1$d-%2$d characters to use the space in search results.'=>'Rozwiń go do %1$d–%2$d znaków, żeby wykorzystać miejsce w wynikach wyszukiwania.','The title is %d characters long and will be cut off in search results.'=>'Tytuł jest za długi (liczba znaków: %d) i zostanie ucięty w wynikach wyszukiwania.','Shorten it to %d characters at most.'=>'Skróć go do maksymalnie %d znaków.','The title is %d characters long.'=>'Liczba znaków w tytule: %d.','There is no meta description.'=>'Brak meta opisu.','Add a description of %1$d-%2$d characters. Without one, the search engine picks a snippet of the content you have no control over.'=>'Dodaj opis o długości %1$d–%2$d znaków. Bez niego wyszukiwarka wybierze fragment treści, na który nie masz wpływu.','The meta description is %d character long, which is short.'=>'Meta opis ma tylko %d znak — to za mało.' . "\0" . 'Meta opis ma tylko %d znaki — to za mało.' . "\0" . 'Meta opis ma tylko %d znaków — to za mało.','Expand it to %1$d-%2$d characters.'=>'Rozwiń go do %1$d–%2$d znaków.','The meta description is %d characters long and will be cut off.'=>'Meta opis jest za długi (liczba znaków: %d) i zostanie ucięty.','The meta description is %d characters long.'=>'Liczba znaków w meta opisie: %d.','The content has about %d word.'=>'Treść ma około %d słowa.' . "\0" . 'Treść ma około %d słów.' . "\0" . 'Treść ma około %d słów.','Below about %d words, content is often seen as thin. Add real information, not filler.'=>'Poniżej ok. %d słów treść bywa oceniana jako uboga. Dodaj konkretne informacje, nie wypełniacz.','There are no images in the content.'=>'W treści nie ma obrazków.','%1$d of %2$d image has no alternative text.'=>'Bez tekstu alternatywnego: %1$d z %2$d obrazka.' . "\0" . 'Bez tekstu alternatywnego: %1$d z %2$d obrazków.' . "\0" . 'Bez tekstu alternatywnego: %1$d z %2$d obrazków.','Fill in the alt attribute: it helps both accessibility and image search.'=>'Uzupełnij atrybut alt — pomaga zarówno dostępności, jak i wyszukiwarce grafiki.','%d image has alternative text.'=>'%d obrazek ma tekst alternatywny.' . "\0" . 'Wszystkie %d obrazki mają tekst alternatywny.' . "\0" . 'Wszystkich %d obrazków ma tekst alternatywny.','There is no slug yet.'=>'Nie ma jeszcze sluga.','Set a readable URL before publishing.'=>'Ustaw czytelny adres URL przed publikacją.','The slug "%s" is just a number.'=>'Slug „%s” to sam numer.','Use a slug that describes the content: a numeric address tells neither people nor search engines anything.'=>'Użyj sluga opisującego treść — numeryczny adres nic nie mówi ani ludziom, ani wyszukiwarkom.','The slug is %d characters long.'=>'Liczba znaków w slugu: %d.','Shorten the address: long slugs are harder to share and more often cut off.'=>'Skróć adres — długie slugi gorzej się udostępnia i częściej są ucinane.','The slug "%s" looks fine.'=>'Slug „%s” wygląda dobrze.','The AI model did not return valid JSON. Try again.'=>'Model AI nie zwrócił poprawnego JSON-a. Spróbuj ponownie.','The AI answer is missing the "%s" field. Try again.'=>'W odpowiedzi AI brakuje pola „%s”. Spróbuj ponownie.','SEO Doctor'=>'SEO Doctor','SEO audit'=>'Audyt SEO','Open'=>'Otwórz','You do not have permission to do this.'=>'Nie masz uprawnień do wykonania tej operacji.','The API key was removed.'=>'Klucz API został usunięty.','Settings saved.'=>'Zapisano ustawienia.','That does not look like an API key. Paste only the key, without quotes or a whole command.'=>'To nie wygląda na klucz API. Wklej sam klucz, bez cudzysłowów i bez całego polecenia.','The API key was saved.'=>'Zapisano klucz API.','You cannot edit this item.'=>'Nie możesz edytować tego elementu.','The AI provider plugin failed. Check its settings under Settings > Connectors.'=>'Wtyczka dostawcy AI zgłosiła błąd. Sprawdź jej ustawienia w Ustawienia → Łączniki.','Set up an AI provider first (see "AI suggestions" below).'=>'Najpierw skonfiguruj dostawcę AI (zobacz „Podpowiedzi AI” poniżej).','Suggestions are ready below.'=>'Podpowiedzi są gotowe poniżej.','You do not have permission to access this page.'=>'Nie masz uprawnień do tej strony.','The audit is read-only: the plugin never overwrites titles, canonicals, sitemaps or schema, so it works alongside Yoast SEO, Rank Math, All in One SEO and SEOPress.'=>'Audyt jest wyłącznie do odczytu: wtyczka nigdy nie nadpisuje tytułów, canonicali, sitemapy ani schema, dzięki czemu współpracuje z Yoast SEO, Rank Math, All in One SEO i SEOPress.','Audit an item'=>'Zbadaj element','Tip: use the "SEO audit" link under any post, page or product in its list.'=>'Wskazówka: użyj linku „Audyt SEO” pod dowolnym wpisem, stroną lub produktem na liście.','Post, page or product ID:'=>'ID wpisu, strony lub produktu:','Audit'=>'Zbadaj','The item was not found, or you cannot edit it.'=>'Nie znaleziono elementu albo nie możesz go edytować.','(no title)'=>'(bez tytułu)','Edit'=>'Edytuj','Meta description read from: %s'=>'Meta opis odczytany z: %s','Status'=>'Status','Result'=>'Wynik','Recommendation'=>'Zalecenie','OK'=>'OK','Critical'=>'Krytyczne','Warning'=>'Uwaga','Suggest a title and description with AI'=>'Zaproponuj tytuł i opis z pomocą AI','Sends the title and up to 4,000 characters of the content to the AI provider.'=>'Wysyła do dostawcy AI tytuł i do 4000 znaków treści.','AI suggestions'=>'Podpowiedzi AI','Copy whatever you find useful into your SEO plugin. Nothing is changed automatically.'=>'Skopiuj do swojej wtyczki SEO to, co uznasz za trafne. Nic nie zmienia się automatycznie.','Title'=>'Tytuł','Description'=>'Opis','Focus keyphrase'=>'Fraza kluczowa','the excerpt'=>'zajawki','nothing found'=>'nie znaleziono','AI suggestions use the AI provider configured in WordPress.'=>'Podpowiedzi AI korzystają z dostawcy AI skonfigurowanego w WordPressie.','Manage connectors'=>'Zarządzaj łącznikami','Optional. AI suggestions use the AI provider configured in WordPress (Settings > Connectors, WordPress 7.0 or later) or, if there is none, your own OpenAI API key below. Requests go straight from this site to the provider, never through DoSieci, and you pay the provider directly.'=>'Opcjonalnie. Podpowiedzi AI korzystają z dostawcy AI skonfigurowanego w WordPressie (Ustawienia → Łączniki, WordPress 7.0 lub nowszy), a jeśli go nie ma — z Twojego własnego klucza API OpenAI poniżej. Zapytania idą bezpośrednio z tej witryny do dostawcy, nigdy przez DoSieci, a za użycie płacisz bezpośrednio dostawcy.','Only an administrator can set up AI suggestions.'=>'Podpowiedzi AI może skonfigurować wyłącznie administrator.','OpenAI API key'=>'Klucz API OpenAI','Leave empty to keep the saved key. The key is never shown in full and never logged.'=>'Zostaw puste, aby zachować zapisany klucz. Klucz nigdy nie jest wyświetlany w całości ani zapisywany w logach.','Remove the saved key'=>'Usuń zapisany klucz','Model'=>'Model','Save'=>'Zapisz']];